#define a 1. //1 or 2

#define PI 3.14159265358979323846
#define PI2 6.28318530717958647693
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    vec2 center = vec2(0.5, 0.5);
    vec2 mouse = iMouse.x>0.?(iMouse.xy / iResolution.xy):vec2(0.7,0.4); //avoid black initial


    vec2 v1 = center - mouse;
    vec2 v2 = uv - mouse;

    float dot = dot(v1, v2);
    float len1 = length(v1);
    float len2 = length(v2);
    float angle = acos(dot / (len1 * len2+ 1e-6))*mouse.x*2.;

    float distance = length(center - uv);

    vec3 col = 0.5 + 0.5 * cos( PI2 + vec3(0.0, 0.333, 0.667) + angle);
    col *= distance*mouse.y*4.;

    fragColor = vec4(col, 1.0);
}
